1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.web.bind.annotation.RequestBody;
9	
10	/**
11	 * Rejects a create request that is missing or blank in any required owner field.
12	 *
13	 * <p>Runs first in the {@code POST /api/owners} pipeline. It binds the body once (this is the only
14	 * step that reads {@code @RequestBody}) and republishes it for {@link BuildOwner}. Each of
15	 * firstName, lastName, address, city and telephone must be present and non-blank; any that are not
16	 * are collected and reported together via {@link OwnerFieldsInvalidException}.
17	 *
18	 * <p>The telephone is converted to E.164 form (see {@link OwnerTelephone#toE164}). The E.164 value
19	 * replaces the submitted one on the republished body, so it is what gets stored and returned. A
20	 * number that cannot form valid E.164 is rejected as an invalid {@code telephone}.
21	 */
22	public class ValidateOwnerFields {
23	
24	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
25	            throws OwnerFieldsInvalidException {
26	        List<String> errors = new ArrayList<>();
27	        if (isBlank(request.getFirstName())) {
28	            errors.add("firstName");
29	        }
30	        if (isBlank(request.getLastName())) {
31	            errors.add("lastName");
32	        }
33	        // The address is normalized (whitespace collapsed, upper-cased, abbreviations expanded)
34	        // before the required-field check, so an address that is blank only after normalization is
35	        // rejected; the normalized value replaces the submitted one, so it is what gets stored,
36	        // returned and compared for household identity.
37	        String address = OwnerAddress.normalize(request.getAddress());
38	        if (address.isEmpty()) {
39	            errors.add("address");
40	        }
41	        else {
42	            request.setAddress(address);
43	        }
44	        if (isBlank(request.getCity())) {
45	            errors.add("city");
46	        }
47	        if (isBlank(request.getTelephone())) {
48	            errors.add("telephone");
49	        }
50	        else {
51	            String telephone = OwnerTelephone.toE164(request.getTelephone());
52	            if (telephone == null) {
53	                errors.add("telephone");
54	            }
55	            else {
56	                request.setTelephone(telephone);
57	            }
58	        }
59	        // Email is optional. When present it must be syntactically valid; it is normalized to
60	        // lower case so it is stored and returned lower-cased.
61	        String email = request.getEmail();
62	        if (email != null) {
63	            if (!OwnerEmail.isValid(email)) {
64	                errors.add("email");
65	            }
66	            else {
67	                request.setEmail(OwnerEmail.normalize(email));
68	            }
69	        }
70	        if (!errors.isEmpty()) {
71	            throw new OwnerFieldsInvalidException(errors);
72	        }
73	        validated.set(request);
74	    }
75	
76	    private static boolean isBlank(String value) {
77	        return value == null || value.isBlank();
78	    }
79	}
