1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Rejects a create request whose normalized telephone is already used by any other owner.
10	 *
11	 * <p>Runs after {@link ValidateOwnerFields} and before {@link BuildOwner}. Both the request and
12	 * every stored owner's telephone are reduced to E.164 through the shared
13	 * {@link OwnerTelephone#toE164} rule before comparison, so differently formatted numbers that
14	 * collapse to the same E.164 value still collide. A match throws
15	 * {@link OwnerTelephoneInUseException}, handled as a 409 Conflict.
16	 */
17	public class CheckOwnerTelephoneUnique {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws OwnerTelephoneInUseException {
21	        String telephone = OwnerTelephone.toE164(request.getTelephone());
22	        if (telephone == null) {
23	            return;
24	        }
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (telephone.equals(OwnerTelephone.toE164(existing.getTelephone()))) {
27	                throw new OwnerTelephoneInUseException(request.getTelephone());
28	            }
29	        }
30	    }
31	}
