1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Rejects a create request whose last name and address, normalized, already belong to another owner.
10	 *
11	 * <p>Runs after {@link ValidateOwnerFields} and before {@link BuildOwner}. Both the request and
12	 * every stored owner's last name and address are reduced through {@link OwnerHousehold#normalize}
13	 * (case-insensitive, whitespace collapsed) before comparison, so differently cased or spaced values
14	 * that mean the same thing still collide. A match throws {@link OwnerHouseholdDuplicateException},
15	 * handled as a 409 Conflict — unless the request opted in with {@code sharesHousehold: true}, which
16	 * permits owners who genuinely share a household.
17	 */
18	public class CheckOwnerHouseholdUnique {
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws OwnerHouseholdDuplicateException {
22	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
23	            return;
24	        }
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (OwnerHousehold.sameHousehold(existing, request.getLastName(),
27	                    request.getAddress())) {
28	                throw new OwnerHouseholdDuplicateException(request.getLastName(),
29	                        request.getAddress());
30	            }
31	        }
32	    }
33	}
