1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Rejects a create request when the owner's city is already at capacity.
9	 *
10	 * <p>Runs after {@link CheckOwnerHouseholdUnique} and before {@link BuildOwner}. A city is at
11	 * capacity once it already contains 50 or more owners; the 51st owner in that city is refused.
12	 * The city is matched exactly, consistent with {@link AssignOwnerCustomerCode}'s per-city
13	 * sequence. A match throws {@link OwnerCityAtCapacityException}, handled as a 409 Conflict.
14	 */
15	public class CheckOwnerCityCapacity {
16	
17	    /** Maximum number of owners permitted per city; the next owner is rejected. */
18	    private static final int CITY_CAPACITY = 50;
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws OwnerCityAtCapacityException {
22	        String city = request.getCity();
23	        if (OwnerCity.countOwnersInCity(ownerRepository, city) >= CITY_CAPACITY) {
24	            throw new OwnerCityAtCapacityException(city);
25	        }
26	    }
27	}
