1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Assigns a shared {@code householdId} when a create request opts in with
10	 * {@code sharesHousehold: true}.
11	 *
12	 * <p>Runs after {@link BuildOwner} in the {@code POST /api/owners} pipeline. The id is derived
13	 * deterministically from the owner's normalized last name and address (see
14	 * {@link OwnerHousehold#householdId}), so every owner that joins the same household computes the
15	 * same value. The joining owner receives the id, and any existing owner in the same household that
16	 * does not yet carry one is backfilled with it — so both ends of a shared household end up with the
17	 * same stable identifier. When the request did not opt in, no id is assigned.
18	 */
19	public class AssignOwnerHousehold {
20	
21	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
22	            OwnerRepository ownerRepository) {
23	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
24	            return;
25	        }
26	        String householdId = OwnerHousehold.householdId(owner.getLastName(), owner.getAddress());
27	        owner.setHouseholdId(householdId);
28	
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (existing.getHouseholdId() == null
31	                    && OwnerHousehold.sameHousehold(existing, owner.getLastName(),
32	                            owner.getAddress())) {
33	                existing.setHouseholdId(householdId);
34	                ownerRepository.save(existing);
35	            }
36	        }
37	    }
38	}
