1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>},
9	 * where {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3}
10	 * is the upper-cased first three letters of the last name and {@code NNNN} is a per-city
11	 * 4-digit zero-padded sequence equal to one more than the number of owners already in
12	 * that city (e.g. {@code LON-SMI-0007}).
13	 */
14	public class AssignOwnerCustomerCode {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String city = owner.getCity();
18	        int sequence = (int) OwnerCity.countOwnersInCity(ownerRepository, city) + 1;
19	        owner.setCustomerCode(String.format("%s-%s-%04d",
20	                first3Upper(city), first3Upper(owner.getLastName()), sequence));
21	    }
22	
23	    /** The upper-cased first three letters of {@code s} (fewer if shorter). */
24	    private static String first3Upper(String s) {
25	        return s.substring(0, Math.min(3, s.length())).toUpperCase();
26	    }
27	}
