6	/**
7	 * Assigns the owner's {@code membershipNumber}, formatted {@code <customerCode>-M<YY>},
8	 * where {@code customerCode} is the owner's previously assigned customer code and
9	 * {@code YY} is the last two digits of the registration date year (e.g.
10	 * {@code LON-SMI-0007-M26}).
11	 */
12	public class AssignOwnerMembershipNumber {
13	
14	    public void service(@Val Owner owner) {
15	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
16	        owner.setMembershipNumber(String.format("%s-M%s", owner.getCustomerCode(), yy));
17	    }
18	}
