1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Thrown by {@link CheckOwnerHouseholdUnique} when a create request carries a last name and address
5	 * that, normalized, already belong to another owner and the request did not opt in with
6	 * {@code sharesHousehold: true}. Handled globally by {@code OwnerHouseholdDuplicateExceptionHandler},
7	 * which responds 409 Conflict.
8	 */
