2	
3	/**
4	 * Single source of truth for the owner-telephone E.164 rule. Both {@link ValidateOwnerFields}
5	 * (which normalizes the submitted value) and {@link CheckOwnerTelephoneUnique} (which compares
6	 * against stored owners) convert through {@link #toE164} so the two can never drift apart.
7	 *
8	 * <p>The rule: strip spaces, dashes and brackets. If what remains starts with a '+', keep that
9	 * leading '+' and country code as-is. Otherwise assume Australian country code '+61', dropping a
10	 * single leading '0' from the national digits before prefixing. The result must be a '+' followed
11	 * by 8 to 15 digits; anything else cannot form valid E.164 and yields {@code null}.
12	 *
13	 * <p>Example: {@code "0412 345 678"} becomes {@code "+61412345678"}.
14	 */
15	final class OwnerTelephone {
16	
17	    private OwnerTelephone() {
18	    }
19	
20	    /**
21	     * Converts a submitted telephone to its E.164 form, or returns {@code null} when the value
22	     * cannot form a valid E.164 number.
23	     */
24	    static String toE164(String value) {
25	        if (value == null) {
26	            return null;
27	        }
28	        // Strip spaces, dashes and brackets; everything else must be a '+' or a digit.
29	        String cleaned = value.replaceAll("[\\s()\\-]", "");
30	        String digits;
31	        if (cleaned.startsWith("+")) {
32	            // Already international: keep the '+' and country code.
33	            digits = cleaned.substring(1);
34	        }
35	        else {
36	            // Assume '+61', dropping a single leading '0' from the national digits.
37	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
38	            digits = "61" + national;
39	        }
40	        // Require 8 to 15 digits (and nothing but digits) after the '+'.
41	        if (!digits.matches("[0-9]{8,15}")) {
42	            return null;
43	        }
44	        return "+" + digits;
45	    }
46	}
